int main() {
    using namespace totk::markers;
    constexpr std::uint32_t wanted[]{KorokStruct, CarryKorokStruct, BossStruct};
    const auto structs = LoadStructs(GameDataList, wanted);
    assert(structs.size() == 2 && structs.contains(KorokStruct) && structs.contains(CarryKorokStruct));
    const auto& koroks = structs.at(KorokStruct);
    assert(koroks.size() == 2);
    assert(MemberFlag(koroks, 6862107189284121298ull) == 0xC084AD2Cu);
    assert(MemberFlag(koroks, 1) == 0);

    std::vector<Marker> places;
    ScanPlaces(LocationArea, 0, places);
    assert(places.size() == 4); // stable, cave, chasm, town; not the other special entrance or the shrine
    const auto find = [&](std::string_view label) {
        for (const auto& m : places)
            if (m.label == label)
                return &m;
        return static_cast<const Marker*>(nullptr);
    };
    const auto* stable = find("TabantaHatago");
    assert(stable && stable->cat == Category::Stable && std::fabs(stable->x + 3200.5f) < 0.01f &&
           std::fabs(stable->z + 1500.25f) < 0.01f);
    const auto* cave = find("Cave_Akkala_0000");
    assert(cave && cave->cat == Category::Cave && std::fabs(cave->y - 299.2f) < 0.01f); // its marker point
    assert(find("DeepHole_Gerudo_01") && find("DeepHole_Gerudo_01")->cat == Category::Cave);
    const auto* town = find("City_Cokiri");
    assert(town && town->cat == Category::Town && std::fabs(town->x - 100.0f) < 0.01f);

    std::vector<Marker> found;
    ScanKoroks(HiddenKorok, &koroks, &structs.at(CarryKorokStruct), found);
    assert(found.size() == 3);
    int flagged = 0, carry = 0;
    for (const auto& m : found) {
        assert(m.cat == Category::Korok);
        if (m.done == Done::Bool) {
            ++flagged;
            assert(m.flag == 0xC084AD2Cu && std::fabs(m.x + 1.5f) < 0.01f);
        } else if (m.done == Done::EnumClear) {
            ++carry;
            assert(m.flag == 1018790570u && m.label == "KorokCarry");
        }
    }
    assert(flagged == 1 && carry == 1);

    assert(ActorCategory("Enemy_Giant_Junior") == Category::Boss);
    assert(ActorCategory("Enemy_Golem_Little") == std::nullopt);
    assert(ActorCategory("Enemy_Mogurudo_Baby_Junior") == std::nullopt);
    assert(ActorCategory("Enemy_Lynel_Senior") == Category::Boss);
    assert(ActorCategory("Enemy_CaveMaster_Middle") == Category::Bubbul);
    assert(ActorCategory("MinusRupee_01") == Category::Poe);
    assert(ActorCategory("Weapon_Sword_021") == Category::Weapon);
    assert(ActorCategory("Weapon_Sword_021_Far") == std::nullopt);
    assert(ActorCategory("Enemy_Bokoblin_Junior") == std::nullopt);
    assert(BossKind("Enemy_Drake_Ice") == "Frost Gleeok");
    std::puts("totk_markers_test: ok");
}
